		"CREATE INDEX IF NOT EXISTS IX_Customers_Name ON Customers(Name);",
		"CREATE TABLE IF NOT EXISTS SalesOrders (Id INTEGER PRIMARY KEY AUTOINCREMENT, OrderNumber TEXT NOT NULL UNIQUE, CustomerId INTEGER NOT NULL REFERENCES Customers(Id), OrderDate TEXT NOT NULL, RequestedDeliveryDate TEXT NULL, Currency TEXT NOT NULL DEFAULT 'EUR', CustomerReference TEXT NULL, Notes TEXT NULL, Status INTEGER NOT NULL DEFAULT 1, CreatedByUserId INTEGER NULL REFERENCES Users(Id), SubmittedByUserId INTEGER NULL REFERENCES Users(Id), SubmittedAtUtc TEXT NULL, ApprovalDecisionByUserId INTEGER NULL REFERENCES Users(Id), ApprovalDecisionAtUtc TEXT NULL, ApprovalComment TEXT NULL, ReleasedByUserId INTEGER NULL REFERENCES Users(Id), ReleasedAtUtc TEXT NULL, CancelledByUserId INTEGER NULL REFERENCES Users(Id), CancelledAtUtc TEXT NULL, CancelReason TEXT NULL, Version INTEGER NOT NULL DEFAULT 1);",
