		"CREATE INDEX IF NOT EXISTS IX_SalesOrderLines_ItemId ON SalesOrderLines(ItemId);",
		"CREATE TABLE IF NOT EXISTS InventoryReservations (Id INTEGER PRIMARY KEY AUTOINCREMENT, SalesOrderLineId INTEGER NOT NULL REFERENCES SalesOrderLines(Id), InventoryId INTEGER NOT NULL REFERENCES Inventories(Id), Quantity INTEGER NOT NULL, Status INTEGER NOT NULL DEFAULT 1, CreatedAtUtc TEXT NOT NULL, CreatedByUserId INTEGER NOT NULL REFERENCES Users(Id), ReleasedAtUtc TEXT NULL, ReleasedByUserId INTEGER NULL REFERENCES Users(Id), Version INTEGER NOT NULL DEFAULT 1, UNIQUE(SalesOrderLineId, InventoryId, Status));",
		"CREATE INDEX IF NOT EXISTS IX_InventoryReservations_Inventory_Status ON InventoryReservations(InventoryId, Status);",
		"CREATE TABLE IF NOT EXISTS Shipments (Id INTEGER PRIMARY KEY AUTOINCREMENT, ShipmentNumber TEXT NOT NULL UNIQUE, SalesOrderId INTEGER NOT NULL REFERENCES SalesOrders(Id), CustomerId INTEGER NOT NULL REFERENCES Customers(Id), ShipmentDate TEXT NOT NULL, Status INTEGER NOT NULL DEFAULT 1, Carrier TEXT NULL, TrackingNumber TEXT NULL, ShippingAddress TEXT NULL, Notes TEXT NULL, CreatedByUserId INTEGER NOT NULL REFERENCES Users(Id), PostedByUserId INTEGER NULL REFERENCES Users(Id), PostedAtUtc TEXT NULL, Version INTEGER NOT NULL DEFAULT 1);",
