		"CREATE INDEX IF NOT EXISTS IX_ShipmentLines_OrderLine ON ShipmentLines(SalesOrderLineId);",
		"CREATE TABLE IF NOT EXISTS SalesInvoices (Id INTEGER PRIMARY KEY AUTOINCREMENT, InvoiceNumber TEXT NOT NULL UNIQUE, CustomerId INTEGER NOT NULL REFERENCES Customers(Id), SalesOrderId INTEGER NOT NULL REFERENCES SalesOrders(Id), ShipmentId INTEGER NOT NULL REFERENCES Shipments(Id), InvoiceDate TEXT NOT NULL, DueDate TEXT NOT NULL, Currency TEXT NOT NULL DEFAULT 'EUR', Status INTEGER NOT NULL DEFAULT 1, CustomerReference TEXT NULL, BillingAddress TEXT NULL, Notes TEXT NULL, CreatedByUserId INTEGER NOT NULL REFERENCES Users(Id), PostedByUserId INTEGER NULL REFERENCES Users(Id), PostedAtUtc TEXT NULL, Version INTEGER NOT NULL DEFAULT 1, UNIQUE(ShipmentId));",
		"CREATE INDEX IF NOT EXISTS IX_SalesInvoices_Customer_Status ON SalesInvoices(CustomerId, Status);",
		"CREATE TABLE IF NOT EXISTS SalesInvoiceLines (Id INTEGER PRIMARY KEY AUTOINCREMENT, SalesInvoiceId INTEGER NOT NULL REFERENCES SalesInvoices(Id), LineNumber INTEGER NOT NULL, SalesOrderLineId INTEGER NOT NULL REFERENCES SalesOrderLines(Id), ShipmentLineId INTEGER NOT NULL REFERENCES ShipmentLines(Id), PartNumber TEXT NOT NULL, Description TEXT NOT NULL, Quantity INTEGER NOT NULL, UnitPrice NUMERIC NOT NULL, DiscountPercent NUMERIC NOT NULL DEFAULT 0, TaxRate NUMERIC NOT NULL DEFAULT 19, Version INTEGER NOT NULL DEFAULT 1, UNIQUE(SalesInvoiceId, LineNumber));"
